insert into public.mealday_ingredients(id,name,unit,pack,price,category,allergen)
select key,value->>'name',value->>'unit',(value->>'pack')::numeric,(value->>'price')::numeric,value->>'category',value->>'allergen' from jsonb_each('{"rice":{"name":"Basmati rice","unit":"g","pack":1000,"price":14,"category":"Pantry"},"pasta":{"name":"Pasta","unit":"g","pack":500,"price":7,"category":"Pantry","allergen":"Gluten"},"chickpeas":{"name":"Chickpeas (drained weight)","unit":"g","pack":240,"price":4,"category":"Pantry"},"lentils":{"name":"Red lentils","unit":"g","pack":500,"price":8,"category":"Pantry"},"bread":{"name":"Bread","unit":"slices","pack":20,"price":7,"category":"Bakery","allergen":"Gluten"},"wraps":{"name":"Tortilla wraps","unit":"wraps","pack":6,"price":8,"category":"Bakery","allergen":"Gluten"},"tomato":{"name":"Tomatoes","unit":"g","pack":500,"price":5,"category":"Vegetables"},"cucumber":{"name":"Cucumber","unit":"g","pack":500,"price":4,"category":"Vegetables"},"onion":{"name":"Onion","unit":"g","pack":1000,"price":5,"category":"Vegetables"},"pepper":{"name":"Bell pepper","unit":"g","pack":500,"price":7,"category":"Vegetables"},"spinach":{"name":"Spinach","unit":"g","pack":200,"price":5,"category":"Vegetables"},"potato":{"name":"Potatoes","unit":"g","pack":1000,"price":6,"category":"Vegetables"},"carrot":{"name":"Carrots","unit":"g","pack":500,"price":3,"category":"Vegetables"},"yogurt":{"name":"Plain yogurt","unit":"g","pack":500,"price":7,"category":"Chilled","allergen":"Milk"},"cheese":{"name":"Cheddar cheese","unit":"g","pack":200,"price":10,"category":"Chilled","allergen":"Milk"},"egg":{"name":"Eggs","unit":"eggs","pack":6,"price":8,"category":"Chilled","allergen":"Egg"},"chicken":{"name":"Chicken breast","unit":"g","pack":500,"price":18,"category":"Chilled"},"tuna":{"name":"Tuna (drained weight)","unit":"g","pack":120,"price":6,"category":"Pantry","allergen":"Fish"},"oil":{"name":"Olive oil","unit":"ml","pack":250,"price":14,"category":"Pantry"},"lemon":{"name":"Lemon","unit":"lemons","pack":3,"price":4,"category":"Vegetables"},"oats":{"name":"Oats","unit":"g","pack":500,"price":7,"category":"Pantry","allergen":"Gluten"}}'::jsonb);
insert into public.mealday_recipes(id,name,minutes,appliances,diet,tags,image,steps)
select x->>'id',x->>'name',(x->>'time')::int,array(select jsonb_array_elements_text(x->'appliances')),x->>'diet',array(select jsonb_array_elements_text(x->'tags')),(x->>'image')::int,x->'steps' from jsonb_array_elements('[{"id":"chickpea-salad","name":"Chickpea crunch salad","time":10,"appliances":[],"diet":"vegan","items":[["chickpeas",120],["tomato",80],["cucumber",80],["lemon",0.25],["oil",5]],"steps":["Drain and rinse the chickpeas. Wash the vegetables.","Dice the tomatoes and cucumber into bite-sized pieces.","Mix the lemon juice and olive oil in a bowl.","Toss the vegetables and chickpeas with the dressing. Season to taste and serve."],"tags":["Quick","Fresh"],"image":2},{"id":"lentil-rice","name":"One-pot lentil rice","time":30,"appliances":["Hob"],"diet":"vegan","items":[["rice",60],["lentils",60],["onion",40],["carrot",60],["oil",5]],"steps":["Rinse the rice and lentils. Dice the onion and carrot.","Warm the oil in a saucepan. Cook the onion and carrot for 5 minutes.","Add rice, lentils and water according to the rice and lentil packet instructions. Simmer covered, adding water as needed.","Cook until the rice and lentils are tender. Rest off the heat for 5 minutes, fluff and serve."],"tags":["Comfort","Family"],"image":0},{"id":"tomato-pasta","name":"Easy tomato pasta","time":20,"appliances":["Hob"],"diet":"vegan","items":[["pasta",90],["tomato",150],["onion",35],["oil",5]],"steps":["Dice the tomatoes and onion. Bring a large pan of water to the boil.","Cook the pasta following the packet instructions. Reserve a mug of cooking water.","Soften the onion in oil. Add the tomatoes and simmer until they break down into a sauce.","Drain the pasta. Toss with the sauce and a splash of reserved water. Season to taste."],"tags":["Quick","Family"],"image":1},{"id":"cheesy-pasta","name":"Creamy spinach pasta","time":25,"appliances":["Hob"],"diet":"vegetarian","items":[["pasta",90],["spinach",60],["yogurt",45],["cheese",20]],"steps":["Bring a large pan of water to the boil. Wash the spinach.","Cook the pasta according to the packet. Stir in the spinach for the last minute.","Reserve some cooking water, then drain. Let the pan cool slightly off the heat.","Stir in yogurt and cheese with a splash of pasta water. Mix gently and serve."],"tags":["Comfort"],"image":1},{"id":"roast-bowl","name":"Roasted vegetable bowl","time":35,"appliances":["Oven","Hob"],"diet":"vegan","items":[["rice",60],["chickpeas",100],["carrot",80],["pepper",80],["oil",7]],"steps":["Heat the oven to 200°C. Rinse and chop the vegetables.","Toss the vegetables with oil on a tray. Roast for 25–30 minutes until tender, turning halfway.","Cook the rice following the packet instructions. Rinse and drain the chickpeas.","Warm chickpeas with the rice. Divide into bowls and top with roasted vegetables."],"tags":["Family","Comfort"],"image":0},{"id":"egg-toast","name":"Tomato eggs on toast","time":15,"appliances":["Hob"],"diet":"vegetarian","items":[["egg",2],["bread",2],["tomato",100],["oil",5]],"steps":["Wash and dice the tomato. Crack the eggs into a bowl and beat.","Warm the oil in a frying pan. Cook the tomatoes for a few minutes.","Add the eggs and stir gently until the egg is set.","Toast or warm the bread in a separate dry pan. Spoon the eggs over it and serve."],"tags":["Quick"],"image":0},{"id":"chicken-rice","name":"Lemon chicken rice bowl","time":30,"appliances":["Hob"],"diet":"meat","items":[["chicken",150],["rice",60],["cucumber",70],["lemon",0.25],["oil",5]],"steps":["Cook the rice following the packet instructions. Wash and slice the cucumber.","Cut the chicken into evenly sized pieces. Keep raw chicken separate from ready-to-eat ingredients.","Heat the oil in a pan. Cook chicken thoroughly, turning regularly, until the thickest part reaches 75°C.","Add lemon juice. Serve chicken with the rice and cucumber."],"tags":["Protein","Family"],"image":0},{"id":"tuna-wrap","name":"Tuna & cucumber wraps","time":10,"appliances":[],"diet":"fish","items":[["tuna",100],["wraps",2],["cucumber",70],["yogurt",30]],"steps":["Drain the tuna. Rinse and dice the cucumber.","Mix the tuna, cucumber and yogurt in a bowl.","Divide the mixture between the wraps.","Fold in the sides, roll up and serve immediately."],"tags":["Quick","Protein"],"image":2},{"id":"air-potato","name":"Air-fryer potato & chickpeas","time":25,"appliances":["Air fryer"],"diet":"vegan","items":[["potato",220],["chickpeas",120],["oil",7],["tomato",60]],"steps":["Wash the potatoes and cut them into small, even cubes. Rinse and dry chickpeas.","Toss potato cubes with oil. Air-fry at 190°C for about 15 minutes, shaking halfway.","Add the chickpeas and cook for another 5–10 minutes until potatoes are tender.","Wash and dice the tomatoes. Serve the hot potatoes and chickpeas with tomatoes."],"tags":["Comfort","Family"],"image":0},{"id":"microwave-potato","name":"Loaded microwave potato","time":15,"appliances":["Microwave"],"diet":"vegetarian","items":[["potato",250],["yogurt",50],["cheese",20],["tomato",60]],"steps":["Wash the potato and prick it several times with a fork.","Place on a microwave-safe plate. Microwave on high for 5 minutes, then turn and cook until tender. Timing depends on your microwave.","Let it stand for 2 minutes. Carefully split it open, allowing hot steam to escape.","Top with yogurt, grated cheese and diced tomato."],"tags":["Quick","Comfort"],"image":0},{"id":"lentil-soup","name":"Carrot & lentil soup","time":30,"appliances":["Hob"],"diet":"vegan","items":[["lentils",75],["carrot",100],["onion",40],["oil",5]],"steps":["Rinse the lentils. Peel and dice the carrots and onion.","Soften the onion in oil in a saucepan. Add carrots and lentils.","Add water following the lentil packet guidance. Simmer, adding water as needed, until tender.","Mash a little with a spoon for a thicker soup. Season and serve."],"tags":["Comfort"],"image":0},{"id":"fresh-wrap","name":"Garden chickpea wraps","time":10,"appliances":[],"diet":"vegan","items":[["chickpeas",120],["wraps",2],["tomato",70],["cucumber",70],["lemon",0.25]],"steps":["Rinse and drain chickpeas. Wash and dice the tomato and cucumber.","Mash chickpeas roughly with a fork and stir in lemon juice.","Add the vegetables and season to taste.","Fill the wraps, roll tightly and serve."],"tags":["Quick","Family"],"image":2},{"id":"rice-egg","name":"Vegetable egg rice","time":20,"appliances":["Hob"],"diet":"vegetarian","items":[["rice",60],["egg",2],["carrot",70],["pepper",60],["oil",5]],"steps":["Cook the rice following its packet instructions. Dice the vegetables and beat the eggs.","Warm the oil in a frying pan. Cook the diced vegetables until tender.","Push vegetables aside, add the beaten eggs and cook until set.","Add the freshly cooked rice. Toss everything together until steaming hot and serve immediately."],"tags":["Quick","Family"],"image":0},{"id":"potato-salad","name":"Lemon potato & chickpea salad","time":25,"appliances":["Hob"],"diet":"vegan","items":[["potato",180],["chickpeas",120],["cucumber",60],["oil",5],["lemon",0.25]],"steps":["Wash and dice potatoes. Simmer in a pan of water until tender.","Drain and let steam dry. Rinse the chickpeas and dice the cucumber.","Mix lemon juice and oil to make a dressing.","Combine potatoes, chickpeas and cucumber with the dressing. Serve warm or cool."],"tags":["Fresh","Family"],"image":2},{"id":"cheese-wrap","name":"Crispy cheese & spinach wraps","time":15,"appliances":["Hob"],"diet":"vegetarian","items":[["wraps",2],["cheese",40],["spinach",70],["tomato",60]],"steps":["Wash the spinach and tomato. Dice the tomato and grate the cheese.","Wilt the spinach in a pan with a splash of water. Drain excess water.","Place spinach, tomato and cheese inside each wrap and fold over.","Warm each folded wrap in a dry frying pan, turning once, until crisp and the cheese has melted."],"tags":["Quick","Comfort"],"image":1},{"id":"simple-rice","name":"Chickpea & spinach rice","time":25,"appliances":["Hob"],"diet":"vegan","items":[["rice",60],["chickpeas",120],["spinach",60],["onion",30],["oil",5]],"steps":["Rinse rice, spinach and drained chickpeas. Dice the onion.","Soften onion in the oil. Add rice and cook with water according to the rice packet.","When rice is almost ready, fold in the chickpeas and spinach. Cover and heat through.","Check that the rice is tender. Rest for a few minutes, fluff and serve."],"tags":["Family","Comfort"],"image":0}]'::jsonb) x;
